import{_ as t,b as a,e as s,a6 as i}from"./chunks/framework.CTTTCP0W.js";const n="/assets/CPU-feature-performance.BFRFc5JM.png",f=JSON.parse('{"title":"CPU feature detection","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cpu-feature-detection.md","filePath":"guide/cpu-feature-detection.md","lastUpdated":1787517273000}'),o={name:"guide/cpu-feature-detection.md"};function r(l,e,p,d,c,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="cpu-feature-detection" tabindex="-1">CPU feature detection <a class="header-anchor" href="#cpu-feature-detection" aria-label="Permalink to &quot;CPU feature detection&quot;">​</a></h1><p>Different processors provide different features and since Graphics32 should aways perform as fast as possible on any given processor, it tries to use the processor optimizations that best fit the CPU of the host system. In order to do this it uses CPU feature detection; When the application starts, Graphics32 queries the CPU about what features it support and based on this selects among its available optimizations.</p><p>:::: right</p><div class="warning custom-block"><p class="custom-block-title">MMX is no longer supported</p><p>Support for the MMX SIMD instruction was deprecated in Graphics32 version 3 and has been removed from version 4.</p><p>Not all documentation has been updated to reflect this, so please ignore all references to MMX code.</p></div><p>::::</p><p>For example, all low-level blend functions have been implemented in at least 4 variants:</p><ul><li>A PUREPASCAL variant written entirely in Pascal with no use of assembler.</li><li>An ASM variant written in regular x86 assembler.</li><li>A MMX assembler variant optimized for the MMX SIMD instruction set.</li><li>A SSE, SSE2 or SSE4.1 assembler variants optimized for the SSE* SIMD instruction sets.</li></ul><p>In addition, most of the assembler variants exists in both a 32-bit and a 64-bit version.</p><p>Generally you do not need to concern yourself about the CPU feature selection; It is completely automatic and transparent to the use of Graphics32. If you <em>do</em> need to control what CPU level features your application uses, you can do so with the following conditional symbols:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td>PUREPASCAL</td><td>Disable all assembler implementations; Only regular Delphi Pascal code will be used.<br>Can be used if the target platform doesn’t support x86 assembler (e.g. Android).</td></tr><tr><td>OMIT_MMX</td><td>Disable the MMX assembler optimizations.</td></tr><tr><td>OMIT_SSE2</td><td>Disable the SSE2 assembler optimizations.<br>Note that this also includes SSE, SSE4.1 and later version of SSE.</td></tr><tr><td>OMIT_MMX and OMIT_SSE2</td><td>Use the x86 assembler optimizations.</td></tr></tbody></table><p>The chart below illustrates the effect of the various optimization levels. The data was generated by the Benchmark example.</p><p><img src="'+n+`" alt="Relative performance of different optimization levels"> Relative performance of different optimization levels</p><h3 id="cpu-features" tabindex="-1">CPU features <a class="header-anchor" href="#cpu-features" aria-label="Permalink to &quot;CPU features&quot;">​</a></h3><p>There are too many different CPU features to list here but the most common ones are declared in the <code>GR32_System</code> unit (via aliases):</p><ul><li>MMX</li><li>ExMMX</li><li>SSE</li><li>SSE2</li><li>SSE3</li><li>SSSE3</li><li>SSE41</li><li>SSE42</li><li>AVX</li><li>AVX2</li><li>AVX512</li></ul><p>The complete list is defined in the <code>GR32.CPUID</code> unit.</p><p>To test for support of a certain CPU feature, use the <code>InstructionSupport</code> member of the global <code>CPU</code> variable (it’s a record):</p><div class="language-pas vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pas</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uses</span></span>
<span class="line"><span>  GR32.CPUID;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>  // Test for SSE4.1 support</span></span>
<span class="line"><span>  if (isSSE41 in CPU.InstructionSupport) then</span></span>
<span class="line"><span>  begin</span></span>
<span class="line"><span>    ... SSE4.1 specific code here ...</span></span>
<span class="line"><span>  end;</span></span>
<span class="line"><span>end;</span></span></code></pre></div>`,18)])])}const m=t(o,[["render",r]]);export{f as __pageData,m as default};
